// Package: Microsoft.Extensions.AI --version 9.*

using Microsoft.Extensions.AI;

// Define a plain static method - no base class needed
public static class OrderTools
{
    public static string GetOrderStatus(string orderId, bool includeTracking = false)
    {
        // Simulated order lookup
        return orderId == "ABC123"
            ? "Order ABC123 | Status: Shipped | Items: 3 | Total: $149.99"
            : "Order not found.";
    }

    public static string CalculateDiscount(string orderId)
    {
        return orderId == "ABC123"
            ? "Eligible for 10% loyalty discount."
            : "Not eligible for discount.";
    }
}

// Wrap the methods as AIFunction instances
var getOrderTool = AIFunctionFactory.Create(
    (string orderId, bool includeTracking = false) => OrderTools.GetOrderStatus(orderId, includeTracking),
    "get_order_status",
    "Return the fulfillment status of an order by ID.");

var discountTool = AIFunctionFactory.Create(
    (string orderId) => OrderTools.CalculateDiscount(orderId),
    "calculate_discount",
    "Check if an order is eligible for a discount.");

// Use with IChatClient
var tools = new[] { getOrderTool, discountTool };
var response = await chatClient.GetResponseAsync(
    [new ChatMessage(ChatRole.User, "Check order ABC123 and apply a discount if eligible.")],
    new ChatOptions { Tools = tools },
    cancellationToken: ct);

Console.WriteLine(response.Text);
// Expected: The model calls get_order_status and calculate_discount automatically.

// Inspect the generated schema
Console.WriteLine(getOrderTool.JsonSchema);
// Expected: { "type": "object", "properties": { "orderId": { "type": "string" }, "includeTracking": { "type": "boolean" } }, "required": ["orderId"] }
